namespace {
using namespace tokspur;
size_t checks=0,batches=0;double worst=0;constexpr float sentinel=-12345.25f,gate=3e-5f;
void need(bool x,const char* why){++checks;if(!x)throw std::runtime_error(why);}
struct Arena{
 MetalGraph& g;std::vector<GpuView> all;
 GpuView values(std::span<const float>x,bool immutable=true){std::vector<std::byte>b(x.size_bytes()+8,std::byte{0x6d});std::memcpy(b.data()+4,x.data(),x.size_bytes());auto v=g.upload(b,"generated GDN chunk fixture",immutable);all.push_back(v);return g.slice(v,4,x.size_bytes());}
 GpuView output(size_t n){return values(std::vector<float>(n,sentinel),false);}
 GpuView zero(size_t n){return values(std::vector<float>(n),false);}
 void guards(){for(auto v:all){const auto b=g.read(v);for(size_t i=0;i<4;++i)need(b[i]==std::byte{0x6d}&&b[b.size()-1-i]==std::byte{0x6d},"GDN chunk view guard");}}
 ~Arena(){try{g.abort();}catch(const FormatError&){}for(auto v:all)g.release(v);}
};
std::vector<float> read(MetalGraph&g,GpuView v){auto b=g.read(v);std::vector<float>x(b.size()/4);std::memcpy(x.data(),b.data(),b.size());return x;}
void close(float x,double y){const double e=std::abs(double(x)-y)/std::max(1.0,std::abs(y));worst=std::max(worst,e);need(std::isfinite(x)&&std::isfinite(y)&&e<=gate,"GDN generated fixed numerical gate");}
void submit(MetalGraph&g,uint64_t count){const auto before=g.memory();const auto done=g.submit();const auto after=g.memory();++batches;need(done.dispatches==count&&before.allocations==after.allocations&&before.live_bytes==after.live_bytes,"GDN encode allocation/dispatch ledger");}
void emit(MetalGraph&g,GdnChunkOp op,GdnChunkParams p,std::initializer_list<std::pair<uint32_t,GpuView>>v){GdnChunkDispatch d{};d.op=op;d.params=p;for(auto [slot,view]:v)d.buffers.at(slot)=view;g.gdn_chunk(d);}
float generated(size_t i,uint32_t seed=44){return float(int((i*131+seed*17)%1993)-996)/997.0f;}
void convolution(MetalGraph&g,uint32_t n,uint32_t columns){
 Arena a{g,{}};const uint32_t stride=columns+3;std::vector<float> h(3*columns),x((n+1)*stride,std::numeric_limits<float>::quiet_NaN()),w(columns*4);for(size_t i=0;i<h.size();++i)h[i]=generated(i)*.01f;for(uint32_t t=0;t<n;++t)for(uint32_t c=0;c<columns;++c)x[t*stride+c]=generated(size_t(t)*columns+c)*.01f;for(size_t i=0;i<w.size();++i)w[i]=generated(i+7)*.25f;
 const auto hv=a.values(h),xv=a.values(x),wv=a.values(w),next=a.output(h.size()),out=a.output((n+1)*stride);GdnChunkParams p{};p.rows=n;p.columns=columns;p.input_stride=p.output_stride=uint64_t(stride)*4;g.begin();emit(g,GdnChunkOp::convolution,p,{{0,hv},{1,xv},{2,wv},{3,next},{4,out}});submit(g,1);const auto got=read(g,out),history=read(g,next);
 const auto source=[&](uint32_t t,uint32_t c){return t<3?h[t*columns+c]:x[(t-3)*stride+c];};for(uint32_t t=0;t<n;++t)for(uint32_t c=0;c<columns;++c){float expected=source(t+3,c)*w[c*4+3];for(uint32_t j=0;j<3;++j)expected+=source(t+j,c)*w[c*4+j];need(got[t*stride+c]==expected,"convolution current-product-first FP32 bits");}for(uint32_t j=0;j<3;++j)for(uint32_t c=0;c<columns;++c)need(history[j*columns+c]==source(n+j,c),"final chronological convolution history");for(uint32_t t=0;t<=n;++t)for(uint32_t c=t<n?columns:0;c<stride;++c)need(got[t*stride+c]==sentinel,"convolution wrote inactive rows/padding");need(read(g,hv)==h,"accepted convolution changed");a.guards();
}
void projection_and_rms(MetalGraph&g,uint32_t n){
 Arena a{g,{}};constexpr uint32_t k=37,r=9,is=43,os=15;std::vector<float>w(k*r),x((n+1)*is,std::numeric_limits<float>::quiet_NaN());for(size_t i=0;i<w.size();++i)w[i]=generated(i)*.01f;for(uint32_t t=0;t<n;++t)for(uint32_t j=0;j<k;++j)x[t*is+j]=generated(size_t(t)*k+j)*.1f;auto wv=a.values(w),xv=a.values(x),out=a.output((n+1)*os);GdnChunkParams p{};p.rows=n;p.columns=k;p.outputs=r;p.input_stride=is*4;p.output_stride=os*4;g.begin();emit(g,GdnChunkOp::projection_f32,p,{{0,wv},{1,xv},{2,out}});submit(g,1);auto got=read(g,out);for(uint32_t t=0;t<n;++t)for(uint32_t j=0;j<r;++j){double y=0;for(uint32_t c=0;c<k;++c)y+=double(w[j*k+c])*x[t*is+c];close(got[t*os+j],y);}for(uint32_t t=0;t<=n;++t)for(uint32_t j=t<n?r:0;j<os;++j)need(got[t*os+j]==sentinel,"projection wrote tail");
 std::vector<float>gains(3);for(uint32_t j=0;j<3;++j)gains[j]=1+float(j)/17;auto gainv=a.values(gains),rms=a.output((n+1)*os);g.begin();g.rms_rows({out,n,r,os*4},gainv,{rms,n,r,os*4},3,1e-6f,true);submit(g,1);auto y=read(g,rms);for(uint32_t t=0;t<n;++t)for(uint32_t group=0;group<3;++group){double sq=0;for(uint32_t j=0;j<3;++j)sq+=double(got[t*os+group*3+j])*got[t*os+group*3+j];const auto inverse=1/std::sqrt(sq/3+1e-6f);for(uint32_t j=0;j<3;++j)close(y[t*os+group*3+j],got[t*os+group*3+j]*inverse*gains[j]);}a.guards();
}
void preparation_and_gates(MetalGraph&g,uint32_t n){
 Arena a{g,{}};constexpr uint32_t heads=48,keyheads=16,dv=128,raw=10240,qstride=6149,xstride=10243,gstride=51;std::vector<float>x((n+1)*xstride,std::numeric_limits<float>::quiet_NaN()),alpha((n+1)*gstride,std::numeric_limits<float>::quiet_NaN()),beta_logits(alpha.size(),std::numeric_limits<float>::quiet_NaN()),rate(heads),bias(heads),gain(dv),raw_output((n+1)*qstride,std::numeric_limits<float>::quiet_NaN()),z(raw_output.size(),std::numeric_limits<float>::quiet_NaN());
 for(uint32_t t=0;t<n;++t){for(uint32_t c=0;c<raw;++c)x[t*xstride+c]=generated(size_t(t)*raw+c)*.03f;for(uint32_t h=0;h<heads;++h){alpha[t*gstride+h]=h==47?700:generated(size_t(t)*heads+h)*3;beta_logits[t*gstride+h]=generated(size_t(t)*heads+h+31)*6;}for(uint32_t c=0;c<heads*dv;++c){raw_output[t*qstride+c]=generated(size_t(t)*heads*dv+c)*.1f;z[t*qstride+c]=generated(size_t(t)*heads*dv+c+17)*6;}}
 for(uint32_t h=0;h<heads;++h){rate[h]=-float(h+1)/97;bias[h]=generated(h)*.1f;}for(uint32_t c=0;c<dv;++c)gain[c]=1+generated(c)*.1f;
 const auto xv=a.values(x),q=a.output((n+1)*qstride),k=a.output((n+1)*qstride),v=a.output((n+1)*qstride),av=a.values(alpha),bv=a.values(beta_logits),rates=a.values(rate),biases=a.values(bias),logg=a.output((n+1)*gstride),beta=a.output((n+1)*gstride),rv=a.values(raw_output),zv=a.values(z),gains=a.values(gain),gated=a.output((n+1)*qstride);GdnChunkParams p{};p.rows=n;p.heads=heads;p.key_heads=keyheads;p.key_width=128;p.value_width=dv;p.input_stride=xstride*4;p.output_stride=p.auxiliary_stride=qstride*4;p.gate_stride=gstride*4;p.query_scale=1/std::sqrt(128.0f);p.l2_epsilon=1e-6f;p.rms_epsilon=1e-6f;
 for(uint32_t policy:{0u,1u}){p.l2_mode=policy;g.begin();emit(g,GdnChunkOp::prepare,p,{{0,xv},{1,q},{2,k},{3,v}});submit(g,1);const auto qr=read(g,q),kr=read(g,k),vr=read(g,v);for(uint32_t t=0;t<n;++t){std::vector<double>in(raw);std::copy_n(x.begin()+size_t(t)*xstride,raw,in.begin());const auto expected=prepare_gdn_reference(in,{2560,keyheads,heads,128,dv,4},{p.query_scale,p.l2_epsilon,L2Mode(policy),p.rms_epsilon});for(uint32_t j=0;j<heads*128;++j){close(qr[t*qstride+j],expected.query[j]);close(kr[t*qstride+j],expected.key[j]);close(vr[t*qstride+j],expected.value[j]);}}for(uint32_t t=0;t<=n;++t)for(uint32_t j=t<n?heads*128:0;j<qstride;++j)need(qr[t*qstride+j]==sentinel&&kr[t*qstride+j]==sentinel&&vr[t*qstride+j]==sentinel,"preparation wrote inactive rows/padding");
 }
 p.input_stride=p.output_stride=p.auxiliary_stride=qstride*4;g.begin();emit(g,GdnChunkOp::gates,p,{{0,av},{1,bv},{2,rates},{3,biases},{4,logg},{5,beta}});emit(g,GdnChunkOp::rms_gate,p,{{0,rv},{1,gains},{2,zv},{3,gated}});submit(g,2);const auto gr=read(g,logg),br=read(g,beta),yr=read(g,gated);
 for(uint32_t t=0;t<n;++t)for(uint32_t h=0;h<heads;++h){close(gr[t*gstride+h],double(rate[h])*stable_softplus(double(alpha[t*gstride+h])+bias[h]));close(br[t*gstride+h],stable_sigmoid(beta_logits[t*gstride+h]));double sq=0;for(uint32_t j=0;j<dv;++j){const auto val=raw_output[t*qstride+h*dv+j];sq+=double(val)*val;}for(uint32_t j=0;j<dv;++j)close(yr[t*qstride+h*dv+j],raw_output[t*qstride+h*dv+j]/std::sqrt(sq/dv+p.rms_epsilon)*gain[j]*stable_sigmoid(z[t*qstride+h*dv+j]));}
 for(uint32_t t=0;t<=n;++t){for(uint32_t j=t<n?heads:0;j<gstride;++j)need(gr[t*gstride+j]==sentinel&&br[t*gstride+j]==sentinel,"gate transform wrote inactive rows/padding");for(uint32_t j=t<n?heads*dv:0;j<qstride;++j)need(yr[t*qstride+j]==sentinel,"RMS gate wrote inactive rows/padding");}a.guards();
}
void active_nonfinite(MetalGraph&g){
 Arena a{g,{}};std::vector<float>state(128,.01f),query(128,.01f),key(128,0),value(1,0),logg(1,0),beta(1,0);query[3]=std::numeric_limits<float>::quiet_NaN();const auto accepted=a.values(state),q=a.values(query),k=a.values(key),v=a.values(value),gv=a.values(logg),bv=a.values(beta),next=a.output(128),out=a.output(1);GdnChunkParams p{};p.rows=1;p.heads=1;p.key_width=128;p.value_width=1;p.input_stride=512;p.auxiliary_stride=p.output_stride=p.gate_stride=4;g.begin();emit(g,GdnChunkOp::fused,p,{{0,accepted},{1,q},{2,k},{3,v},{4,gv},{5,bv},{6,next},{8,out}});bool refused=false;try{static_cast<void>(g.submit());}catch(const FormatError&){refused=true;}need(refused,"active NaN hidden by beta0");try{g.abort();}catch(const FormatError&){}need(read(g,accepted)==state,"failed recurrence changed accepted state");a.guards();
}
void core(MetalGraph&g,uint32_t n,uint32_t heads,uint32_t dv,bool cs64,bool strong_decay=false){
 Arena a{g,{}};const uint32_t dk=128,qs=heads*dk+3,vs=heads*dv+5,gs=heads+2;const size_t state_count=size_t(heads)*dk*dv;std::vector<float>s(state_count),q((n+1)*qs,std::numeric_limits<float>::quiet_NaN()),k(q.size(),std::numeric_limits<float>::quiet_NaN()),v((n+1)*vs,std::numeric_limits<float>::quiet_NaN()),logg((n+1)*gs,std::numeric_limits<float>::quiet_NaN()),beta(logg.size(),std::numeric_limits<float>::quiet_NaN());std::vector<double>qr,kr,vr,gr,br;
 for(size_t i=0;i<s.size();++i)s[i]=generated(i)*.01f;
 for(uint32_t t=0;t<n;++t){for(uint32_t h=0;h<heads;++h){for(uint32_t j=0;j<dk;++j){q[t*qs+h*dk+j]=generated((size_t(t)*heads+h)*dk+j)*.01f;k[t*qs+h*dk+j]=generated((size_t(t)*heads+h)*dk+j+31)*.01f;qr.push_back(q[t*qs+h*dk+j]);kr.push_back(k[t*qs+h*dk+j]);}for(uint32_t j=0;j<dv;++j){v[t*vs+h*dv+j]=generated((size_t(t)*heads+h)*dv+j+17)*.03f;vr.push_back(v[t*vs+h*dv+j]);}logg[t*gs+h]=strong_decay?-1000.0f:-float((t+h)%7+1)/97;beta[t*gs+h]=float((t+h)%13)/12;gr.push_back(logg[t*gs+h]);br.push_back(beta[t*gs+h]);}}
 const auto expected=gdn_chunk_reference(std::vector<double>(s.begin(),s.end()),qr,kr,vr,gr,br,heads,dk,dv,n,1);const auto accepted=a.values(s),qv=a.values(q),kv=a.values(k),vv=a.values(v),gv=a.values(logg),bv=a.values(beta),next=a.output(state_count),out=a.output((n+1)*vs);GdnChunkParams p{};p.rows=n;p.heads=heads;p.key_width=dk;p.value_width=dv;p.input_stride=qs*4;p.auxiliary_stride=p.output_stride=vs*4;p.gate_stride=gs*4;
 if(!cs64){g.begin();emit(g,GdnChunkOp::fused,p,{{0,accepted},{1,qv},{2,kv},{3,vv},{4,gv},{5,bv},{6,next},{8,out}});submit(g,1);}
 else{const auto prefix=a.zero(heads*64),lower=a.zero(heads*64*64),attention=a.zero(heads*64*64),residual=a.zero(64*heads*dv),sa=a.zero(state_count),sb=a.zero(state_count);auto current=accepted;uint32_t chunk=0;g.begin();for(uint32_t offset=0;offset<n;offset+=64,++chunk){p.offset=offset;p.count=std::min(64u,n-offset);auto destination=offset+p.count==n?next:(chunk%2?sb:sa);emit(g,GdnChunkOp::prefix64,p,{{0,gv},{1,prefix}});emit(g,GdnChunkOp::coefficients64,p,{{0,qv},{1,kv},{2,prefix},{3,bv},{4,lower},{5,attention}});emit(g,GdnChunkOp::solve64,p,{{0,current},{1,kv},{2,vv},{3,prefix},{4,bv},{5,lower},{6,residual}});emit(g,GdnChunkOp::emit64,p,{{0,current},{1,qv},{2,kv},{3,prefix},{4,attention},{5,residual},{6,destination},{8,out}});current=destination;}submit(g,4*((n+63)/64));}
 auto actual=read(g,out),actual_state=read(g,next);for(uint32_t t=0;t<n;++t)for(uint32_t j=0;j<heads*dv;++j)close(actual[t*vs+j],expected.output[size_t(t)*heads*dv+j]);for(size_t i=0;i<actual_state.size();++i)close(actual_state[i],expected.state[i]);for(uint32_t t=0;t<=n;++t)for(uint32_t j=t<n?heads*dv:0;j<vs;++j)need(actual[t*vs+j]==sentinel,"recurrence wrote tail");need(read(g,accepted)==s,"accepted matrix changed");a.guards();
}
}
int main(int argc,char**argv){try{if(argc!=4||std::string(argv[1])!="--allow-gpu"||(std::string(argv[3])!="quick"&&std::string(argv[3])!="target"))throw std::runtime_error("usage: --allow-gpu OWNED_METALLIB quick|target; requires the root exclusive GPU owner");MetalGraph g(argv[2],512ull*1024*1024);g.prepare_gdn_chunk();const auto initial=g.memory().live_bytes;for(uint32_t n:{1,2,3,7,8,31,63,64,65,127,128,129,255,256,511,512}){convolution(g,n,31);projection_and_rms(g,n);core(g,n,3,7,false);core(g,n,3,7,true);}for(uint32_t n:{1,3,65})preparation_and_gates(g,n);core(g,65,1,3,false,true);core(g,65,1,3,true,true);active_nonfinite(g);if(std::string(argv[3])=="target"){convolution(g,512,10240);core(g,512,48,128,false);core(g,512,48,128,true);}need(g.memory().live_bytes==initial,"GDN component leaked buffers");std::cout<<"GDN generated GPU checks "<<checks<<", batches "<<batches<<", worst scaled error "<<worst<<", fixed gate "<<gate<<" pass; no model or admission\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
